#!/usr/bin/env python3
"""Génère docs/sources/3am/unit2/extraction.json — 3AM, unité 2 « العمليات على الكسور والأعداد الناطقة » (manuel الجيل الثاني, منشورات الشهاب 2017 ;
pp. 22–36 du livre = PDF 23–37 : DANS CETTE UNITÉ pdf = livre + 1 ; la p. 37 du livre (ICT) manque au scan — docs/sources/3am/textbook-map.json).

Transcription VISUELLE (pages rendues à 110 dpi ; les passages douteux relus à 220 dpi ; le scan n'a pas de couche texte). Tout ce qui va à la leçon générée
MAINTENANT (maqlub-qismat-kasrayn, L1) est `verified: True` ; les éléments des autres leçons sont transcrits plus brièvement, `verified: False` : chaque
leçon relira les siens à 200–250 dpi. Les réponses sont CALCULÉES ici (Fraction exacte), jamais tapées (`answerSource: computed`).

LECTURE DES ÎLOTS DU SCAN : les expressions sont des îlots LTR dans du texte RTL, et le scan les imprime parfois à l'envers. Les seules lectures qui
correspondent aux options imprimées sont : `prep` 7 = 4/3 − 8/15 = 4/5 ; `prep` 11 = (−8) − (−12) = 4 ; `prep` 12 = (−7) ÷ (−2) = 7/2 ; `self-1` =
8/9 ÷ 4/3 = 2/3 (le PLAN écrivait « 4/3 ÷ 8/9 = 3/2 » : 3/2 n'est dans aucune option — erreur de plan corrigée, voir discrepancies).

FRONTIÈRES entre les leçons de l'unité (ce que chacune possède ; le plan README détaille) :
  • maqlub-qismat-kasrayn (L1, générée MAINTENANT) — r03, r04 : le مقلوب d'un naturel, d'un décimal ou d'un VRAI fraction POSITIVE (1/a, b/a), x × 1/x = 1,
    0 n'a pas de مقلوب, ÷ b = × 1/b, a/b ÷ c/d = a/b × d/c (termes naturels), simplifier avant de multiplier, fraction composée à termes positifs. N'a JAMAIS
    le مقلوب d'un NÉGATIF (amaliyat-natiqa), n'additionne jamais, ne compare pas.
  • tasawi-muqaranat-kasrayn (L2) — a/b = c/d ⇔ ad = bc (deux sens, terme manquant), comparer deux fractions POSITIVES de dénominateurs quelconques (dénominateur
    commun), choix de la méthode. Ni somme ni comparaison de fractions SIGNÉES.
  • jam-tarh-kasrayn (L3) — somme et différence de fractions POSITIVES sans multiple d'un dénominateur dans l'autre, plus petit multiple commun, réduire.
    Une différence NÉGATIVE est à amaliyat-natiqa.
  • adad-natiq (L4) — le nombre rationnel, inclusions, écritures à dénominateur positif, droite graduée, comparaison / rangement, entier + fraction.
    Ni le signe d'un quotient (qismat-nisbiyayn), ni « décimal ou non » (1AM), ni π (4AM).
  • amaliyat-natiqa (L5) — les quatre opérations sur deux rationnels, le مقلوب d'un négatif, enchaînements, fractions composées, valeurs de lettres.
  • wadiya-idmajiya-kusur-natiqa (S) — aucune connaissance nouvelle : six situations d'entraînement, la situation finale analysée (le تحدّ), le test final.
Les bases 2AM (jida-kasrayn, muqarana-kasrayn, jam-tarh-kusur, kasr-hasil-qisma) et 3AM unité 1 (qismat-nisbiyayn, jidaa-adadayn-nisbiyayn) sont RAPPELÉES.

L'unité est générée LEÇON PAR LEÇON : les destinations vers une leçon encore coming_soon sont EN ATTENTE (scripts/check-textbook-coverage.mjs).
Usage : python3 docs/sources/3am/unit2/build-extraction.py
"""
import json
from decimal import Decimal as D
from fractions import Fraction as F
from pathlib import Path


def dec(s):
    return D(str(s).replace(',', '.').replace(' ', ''))


def q(s):
    s = str(s).replace(' ', '')
    if '/' in s:
        n, d = s.split('/')
        return q(n) / q(d)
    return F(dec(s))


def frac(x):
    x = F(x)
    return str(x.numerator) if x.denominator == 1 else f'{x.numerator}/{x.denominator}'


def fr(x):
    x = F(x)
    s = format((D(x.numerator) / D(x.denominator)).normalize(), 'f')
    assert F(D(s)) == x, f'{x} n’est pas décimal'
    return s.replace('.', ',')


E = []


def el(id, kind, page, section, text=None, verified=False, **extra):
    d = {'id': id, 'kind': kind, 'page': page, 'section': section, 'verified': verified}
    if text is not None:
        d['text'] = text
    d.update(extra)
    E.append(d)
    return d


L1, L2, L3, L4, L5, S = ('maqlub-qismat-kasrayn', 'tasawi-muqaranat-kasrayn', 'jam-tarh-kasrayn', 'adad-natiq', 'amaliyat-natiqa',
                         'wadiya-idmajiya-kusur-natiqa')

